  // --- greedy purchase loop (macro actions: build@tier, upgrade xN, sell+replace@tier) ---
  var gold = state.gold, acts = [], spent = [];
  for (s = 0; s < 16; s++) { var tu2 = state.slots[s] && state.slots[s].turret; spent.push(tu2 ? (tu2.spent | 0) : 0); }
  work = 0;
  var baseJ = evalCfg(H), baseLeak = rEarly;
  var TC = [0, 1, 2, 4];
  while (acts.length < 28 && work < P.budget) {
    var need = baseLeak > 0 || gold > P.cap;
    if (!need) break;
    var spendable = baseLeak > 0 ? gold : gold - P.cap;
    var bS = -1, bT = 0, bK = 0, bCost = 0, bestGain = P.minGain, bestJ = 0, bestLeak = 0;
    var nEmpty = 0;
    for (s = 0; s < 16; s++) if (cfgType[s] < 0) nEmpty++;
    var allowRep = nEmpty <= P.repEmpty && w >= P.repWave;
    for (s = 0; s < 16 && work < P.budget; s++) {
      var oT = cfgType[s], oK = cfgTier[s], refund = oT >= 0 ? Math.floor(spent[s] * 70 / 100) : 0;
      for (var tt = 0; tt < 5; tt++) {
        if (oT >= 0 && tt !== oT && !allowRep) continue;
        if (!rangeTab(tt, 3, s).any) continue;
        for (var kk = 1; kk <= 3; kk++) {
          var cost;
          if (tt === oT) { if (kk <= oK) continue; cost = T_COST[tt] * (TC[kk] - TC[oK]); }
          else {
            cost = T_COST[tt] * TC[kk] - refund;
            if (oT >= 0 && T_COST[tt] * TC[kk] <= spent[s]) continue;
          }
          if (cost > spendable) break;
          if (oT < 0 && kk > P.maxBuildTier) break;
          cfgType[s] = tt; cfgTier[s] = kk;
          var J = evalCfg(H), g = (baseJ - J) / Math.pow(cost < 25 ? 25 : cost, P.alpha);
          if (tt !== oT && oT >= 0) g *= P.repPen;
          if (g > bestGain) { bestGain = g; bS = s; bT = tt; bK = kk; bCost = cost; bestJ = J; bestLeak = rEarly; }
        }
      }
      cfgType[s] = oT; cfgTier[s] = oK;
    }
    if (bS < 0) break;
    var k0 = cfgTier[bS];
    if (cfgType[bS] !== bT) {
      if (cfgType[bS] >= 0) acts.push({ op: "sell", slot: bS });
      acts.push({ op: "build", slot: bS, type: TN[bT] });
      k0 = 1; spent[bS] = 0;
    }
    for (; k0 < bK; k0++) acts.push({ op: "upgrade", slot: bS });
    cfgType[bS] = bT; cfgTier[bS] = bK; spent[bS] = T_COST[bT] * TC[bK];
    gold -= bCost; baseJ = bestJ; baseLeak = bestLeak;
  }
  return acts;
}

