  // --- greedy purchase loop (macro actions: build@tier, upgrade xN, sell+replace@tier) ---
  var gold = state.gold, acts = [], spent = [];
  for (s = 0; s < 16; s++) { var tu2 = state.slots[s] && state.slots[s].turret; spent.push(tu2 ? (tu2.spent | 0) : 0); }
  work = 0;
  var baseJ = evalCfg(H), baseLeak = rEarly;
  var TC = [0, 1, 2, 4], FIN = P.FIN;
  var capNow = w <= P.w0 ? P.cap : w >= P.w1 ? 0 : P.cap * (P.w1 - w) / (P.w1 - P.w0);
  var list = [], touched = [], stale = false;
  function applyCand(c) {
    var sl = c[2], k0 = cfgTier[sl];
    if (cfgType[sl] !== c[3]) {
      if (cfgType[sl] >= 0) acts.push({ op: "sell", slot: sl });
      acts.push({ op: "build", slot: sl, type: TN[c[3]] });
      k0 = 1;
    }
    for (; k0 < c[4]; k0++) acts.push({ op: "upgrade", slot: sl });
    cfgType[sl] = c[3]; cfgTier[sl] = c[4]; spent[sl] = T_COST[c[3]] * TC[c[4]];
    gold -= c[1]; touched[sl] = 1;
  }
  while (acts.length < 27) {
    if (!(baseLeak > 0 || gold > capNow)) break;
    var spendable = baseLeak > 0 ? gold : gold - capNow;
    if (work >= P.budget) {
      // out of compute: keep spending from the last ranked list (stale gains), one action per untouched slot
      if (!stale) { stale = true; list.sort(function (a, b) { return b[0] - a[0]; }); }
      var did = false;
      for (i = 0; i < list.length; i++) {
        var c = list[i];
        if (touched[c[2]] || c[1] > spendable) continue;
        applyCand(c); did = true; break;
      }
      if (!did) break;
      continue;
    }
    list.length = 0;
    var bi = -1, bestGain = P.minGain;
    for (s = 0; s < 16 && work < P.budget; s++) {
      var oT = cfgType[s], oK = cfgTier[s], refund = oT >= 0 ? Math.floor(spent[s] * 70 / 100) : 0;
      for (var pass = 0; pass < 2; pass++) {
        var tt = pass === 0 ? 0 : FIN[s];
        if (pass === 1 && tt === 0) break;
        if (oT >= 0 && tt !== oT && (oT !== 0 || w < P.repWave)) continue;   // only bolts get replaced, by the slot's final type
        if (!rangeTab(tt, 3, s).any) continue;
        for (var kk = 1; kk <= 3; kk++) {
          var cost;
          if (tt === oT) { if (kk <= oK) continue; cost = T_COST[tt] * (TC[kk] - TC[oK]); }
          else {
            cost = T_COST[tt] * TC[kk] - refund;
            if (oT >= 0 && T_COST[tt] * TC[kk] <= spent[s]) continue;
          }
          if (cost > spendable) break;
          if (oT < 0 && kk > P.maxBuildTier) break;
          cfgType[s] = tt; cfgTier[s] = kk;
          var J = evalCfg(H), g = (baseJ - J) / Math.pow(cost < 25 ? 25 : cost, P.alpha);
          if (tt !== oT && oT >= 0) g *= P.repPen;
          if (g > P.minGain) {
            list.push([g, cost, s, tt, kk, J, rEarly]);
            if (g > bestGain) { bestGain = g; bi = list.length - 1; }
          }
        }
      }
      cfgType[s] = oT; cfgTier[s] = oK;
    }
    if (bi < 0) break;
    var bc = list[bi];
    applyCand(bc); touched[bc[2]] = 0;
    baseJ = bc[5]; baseLeak = bc[6];
    list.splice(bi, 1);
    for (i = list.length - 1; i >= 0; i--) if (list[i][2] === bc[2]) list.splice(i, 1);
  }
  return acts;
}

