import AppKit
import WebKit

// usage: wk <fileURL-or-path> <width> <height> <steps.json>
// steps: [{"wait":1.0},{"js":"return ..."},{"shot":"/path.png"}]
let args = CommandLine.arguments
let pagePath = args[1]
let W = Double(args[2])!, H = Double(args[3])!
let stepsData = try! Data(contentsOf: URL(fileURLWithPath: args[4]))
let steps = try! JSONSerialization.jsonObject(with: stepsData) as! [[String: Any]]

final class Runner: NSObject, WKNavigationDelegate {
    var web: WKWebView!
    var win: NSWindow!
    var idx = 0
    func start() {
        let cfg = WKWebViewConfiguration()
        let hook = """
        window.__errs = [];
        window.addEventListener('error', function (e) { window.__errs.push('ERR ' + (e.message || e) + ' @' + (e.filename || '') + ':' + (e.lineno || '')); });
        window.addEventListener('unhandledrejection', function (e) { window.__errs.push('REJ ' + e.reason); });
        (function () { var ce = console.error; console.error = function () { window.__errs.push('CE ' + Array.prototype.join.call(arguments, ' ')); ce.apply(console, arguments); };
          var cw = console.warn; console.warn = function () { window.__errs.push('CW ' + Array.prototype.join.call(arguments, ' ')); cw.apply(console, arguments); }; })();
        """
        cfg.userContentController.addUserScript(WKUserScript(source: hook, injectionTime: .atDocumentStart, forMainFrameOnly: true))
        cfg.preferences.setValue(true, forKey: "allowFileAccessFromFileURLs")
        web = WKWebView(frame: NSRect(x: 0, y: 0, width: W, height: H), configuration: cfg)
        web.navigationDelegate = self
        win = NSWindow(contentRect: NSRect(x: 40, y: 40, width: W, height: H), styleMask: [.borderless], backing: .buffered, defer: false)
        win.contentView = web
        win.orderFrontRegardless()
        let url = URL(fileURLWithPath: pagePath)
        web.loadFileURL(url, allowingReadAccessTo: url.deletingLastPathComponent())
    }
    func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
        print("LOADED")
        next()
    }
    func webView(_ webView: WKWebView, didFail navigation: WKNavigation!, withError error: Error) { print("FAIL \(error)"); exit(2) }
    func webView(_ webView: WKWebView, didFailProvisionalNavigation navigation: WKNavigation!, withError error: Error) { print("FAILP \(error)"); exit(2) }
    func next() {
        if idx >= steps.count { fflush(stdout); exit(0) }
        let st = steps[idx]; idx += 1
        if let w = st["wait"] as? Double {
            DispatchQueue.main.asyncAfter(deadline: .now() + w) { self.next() }
        } else if let js = st["js"] as? String {
            web.callAsyncJavaScript(js, arguments: [:], in: nil, in: .page) { res in
                switch res {
                case .success(let v): print("JS> \(v)")
                case .failure(let e): print("JSERR> \(e)")
                }
                fflush(stdout)
                self.next()
            }
        } else if let path = st["shot"] as? String {
            let sc = WKSnapshotConfiguration()
            sc.afterScreenUpdates = true
            web.takeSnapshot(with: sc) { img, err in
                if let img = img, let tiff = img.tiffRepresentation, let rep = NSBitmapImageRep(data: tiff), let png = rep.representation(using: .png, properties: [:]) {
                    try? png.write(to: URL(fileURLWithPath: path))
                    print("SHOT \(path) \(rep.pixelsWide)x\(rep.pixelsHigh)")
                } else { print("SHOTFAIL \(String(describing: err))") }
                fflush(stdout)
                self.next()
            }
        } else { next() }
    }
}

let app = NSApplication.shared
app.setActivationPolicy(.accessory)
let runner = Runner()
DispatchQueue.main.async { runner.start() }
DispatchQueue.main.asyncAfter(deadline: .now() + 240) { print("TIMEOUT"); exit(3) }
app.run()

